python3 -I - <<'EOF'
p='game.package.js'
s=open(p).read()
def sub(a,b):
    global s
    assert s.count(a)==1,a
    s=s.replace(a,b)
sub('state: { t: "f64", depth: "f64", miner: struct({ x: "f64", y: "f64" }), start: "cell2" },',
    'state: { t: "f64", depth: "f64", miner: struct({ x: "f64", y: "f64" }), start: "cell2", gone: "bool" },')
sub('/** One tick: a new level puts the miner at its start; the pad moves the miner; standing on the exit goes down. */',
'''/**
 * One tick: a new level puts the miner at its start; the pad moves the miner; reaching the exit goes down, once per
 * level (`gone` holds until the next level arrives, which may be several ticks later).
 */''')
sub('''  return { t: s.t + ctx.dt, depth: onExit ? s.depth + 1 : s.depth, miner, start: [sx, sy] };''',
'''  const left = !arrived && s.gone; // this level's exit was already taken
  const depth = onExit && !left ? s.depth + 1 : s.depth;
  return { t: s.t + ctx.dt, depth, miner, start: [sx, sy], gone: left || onExit };''')
sub('init: () => ({ t: 0, depth: 0, miner: { x: -1, y: -1 }, start: [-1, -1] }),',
    'init: () => ({ t: 0, depth: 0, miner: { x: -1, y: -1 }, start: [-1, -1], gone: false }),')
open(p,'w').write(s)
EOF
cat > /dev/null <<'EOF'
EOF
node --input-type=module -e '
import fs from "node:fs";
const {carve} = await import("data:text/javascript,"+encodeURIComponent(fs.readFileSync("carve.js","utf8")));
const src = fs.readFileSync("game.package.js","utf8");
const body = src.slice(src.indexOf("const IDLE"), src.indexOf("export const gameRuntime")).replace("export function","function");
const gameStep = new Function(body+"return gameStep")();
const control=(m,p)=>{m.dx=p.right?1:p.left?-1:0;m.dy=p.down?1:p.up?-1:0};
// stand-in: ticks at k/30, host reads depth every `per` ticks, new level seen from the next tick
function sim(per, script, n=45){
  let s={t:0,depth:0,miner:{x:-1,y:-1},start:[-1,-1],gone:false}, d=0, lv=carve(7,0,45), log=[];
  for(let k=1;k<=n;k++){
    const pad={up:false,down:false,left:false,right:false,...script(k)};
    const b=s.depth;
    s=gameStep(s,{inputs:{start:[lv.start.x,lv.start.y],exit:[lv.exit.x,lv.exit.y]},controls:{pad},kernels:{control},dt:1/30});
    if(s.depth!==b) log.push(`${k}/30:${s.depth}`);
    if(k%per===0&&s.depth!==d){d=s.depth;lv=carve(7,d,45);}
  }
  return `depth ${s.depth} [${log}] miner ${s.miner.x},${s.miner.y}`;
}
for(const per of [1,2,3,4,6,15]) console.log("per",per,"session:",sim(per,k=>({right:k<=7})), "| held:",sim(per,k=>({right:k<=7}),45)===sim(per,k=>({right:k<=7})));
console.log("wiggle on exit:",sim(15,k=>k<=7?{right:true}:k==8?{left:true}:k==9?{right:true}:{}));
console.log("two levels:",sim(3,k=>({right:k<=7||(k>=20&&k<=22)})));
'
